elif isinstance(target, type) and isinstance(type(target).__call__, _C_SLOTS):
    # type.__call__ runs the class's own __new__ and __init__, as inspect.signature reads
    # them: a partial bound there is fixed too, or the class is refused.
    for attr in ("__new__", "__init__"):
        member = inspect.getattr_static(target, attr, None)
        member = getattr(member, "__func__", member)  # staticmethod, classmethod
        if isinstance(member, functools.partialmethod):
            found.update(member.keywords)
        elif isinstance(member, functools.partial):
            found.update(member.keywords)
    return frozenset(found)
